/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void display_once (Display_Type type, UInt32 timeout)
{	
  Display_Cmd display_cmd_new ;

  timeout_stop  (display_timeout) ;	

  display_cmd_new.id = DISPLAY_ONCE ;

  display_cmd_new.arg.cmd_once.type    = type    ;
  display_cmd_new.arg.cmd_once.timeout = timeout ;

  display_pass_cmd (& display_cmd_new) ;
}

